from research_helpers import *
I=ev('https://www.iconplc.com/solutions/technologies','Official named clinical-research technology catalogue reviewed; generic service headings and customer-sponsored drugs excluded. Repeated technologies consolidated.')
rows=[('ICONex','Clinical expert-network visualization.'),('One Search','Clinical-trial site-selection technology.'),('Cassandra','Predictive postmarketing-requirements research tool.'),('HORIZON','Clinical study start-up platform.'),('SmartDraft','Clinical site-contract drafting tool.'),('ICON Digital Platform','Clinical-trial patient-services platform supporting consent and outcome assessments.'),('FIRECREST','Clinical-site training and document portal.'),('iSubmit','Electronic trial-master-file document automation.'),('Clinical Data Studio','Clinical data integration and monitoring platform.'),('Flex Advantage','Interactive response and trial randomization/supply-management system.'),('LabView360','Clinical laboratory operations platform.'),('WorkBench','Statistical computing environment for clinical research.'),('Orbis','Clinical-research workflow assistant platform.'),('ICOMaster','Electronic trial master file platform.'),('CARD','Clinical-data sharing platform for investigator sites.'),('MRT COA','Clinical outcome-assessment research intelligence.'),('ORCA Safety','Drug safety monitoring rules engine.'),('Signet','Benefit-risk and safety-signal visualization.'),('NONMEM','Population pharmacokinetic/pharmacodynamic modelling software.'),('PDx-POP','Population pharmacokinetic modelling workflow software.')]
ip=[p(n,d,I,'commercial',roles=['commercial_partner'],typ='product',sub='research_tools')for n,d in rows]
N=ev('https://www.nissanchem.co.jp/eng/products/materials/semiconductor.html','Nissan Chemical manufactures and sells ARC coatings under BrewerScience license since1997; no invented individual grade identifiers.')
O=ev('https://www.nissanchem.co.jp/eng/ir_info/library/pdf/AM/am2019_03.pdf','Official named OptiStack multilayer semiconductor-process materials business.')
H=ev('https://www.nissanchem.co.jp/eng/products/healthcare/drug_discovery.html','Official medicine discovery history, marketed LIVALO/LANDEL/EPATEC and NTC801 arrhythmia-development candidate. Product developer distinguished from current third-party brand owner.')
B=ev('https://www.nissanchem.co.jp/eng/products/advance/hb.html','Official life-science research materials and platforms: FCeM, FCeMAdvance,Cellhesion,prevelex,prevelex-CAT,Cegnet. No approval or launch assumed for newly developed attachment/detachment platforms.')
A=ev('https://www.nissanchem.co.jp/eng/ir_info/archive/ar/ar2023_17.pdf','Official report documents SUNCONNECT paid sales for semiconductor package substrates, CellhesionMS and prevelexCC1 specific research-material grades.')
np=[p('ARC coating','Bottom anti-reflective coatings for semiconductor lithography.',N,'commercial',roles=['manufacturer','licensee'],typ='product',sector='semiconductors',sub='materials_and_packaging'),p('OptiStack','Multilayer semiconductor-process materials.',O,'commercial',typ='product',sector='semiconductors',sub='materials_and_packaging'),p('SUNCONNECT','Optical interconnect material for semiconductor packaging.',A,'commercial',typ='product',sector='semiconductors',sub='materials_and_packaging')]
for n,d,life in [('LIVALO','Pitavastatin calcium medicine developed by Nissan Chemical and marketed by Kowa.','commercial'),('LANDEL','Efonidipine hydrochloride medicine; also branded FINTE in South Korea.','commercial'),('EPATEC','Topical ketoprofen preparation; transferred to Zeria in2008.','unknown'),('NTC-801','Acetylcholine-sensitive potassium-channel inhibitor for arrhythmia.','development')]:
 np.append(p(n,d,H,life,typ='product'if life=='commercial'else'development_program',aliases=['FINTE']if n=='LANDEL'else[]))
for n,d,life in [('FCeM','Three-dimensional suspension cell-culture material family.','commercial'),('FCeM Advance','Non-freeze spheroid/organoid storage and transport material.','commercial'),('Cellhesion','Cell culture scaffold material family.','commercial'),('prevelex','Biological anti-adhesion coating material family.','commercial'),('prevelex-CAT','Cell attachment/detachment material for spheroid production.','unknown'),('Cegnet','Suspension-cell attachment/detachment technology for gene-therapy manufacturing.','development')]:np.append(p(n,d,B,life,typ='product',sub='research_tools'))
for n,d in [('Cellhesion-MS','Mesenchymal stem-cell culture scaffold grade.'),('prevelex CC1','Anti-adhesion coating grade used for iPSC cardiomyocyte spheroid production.')]:np.append(p(n,d,A,'commercial',typ='product',sub='research_tools'))
cs=[company('ICON PLC',ip,[I],'Named clinical-research tools captured. CRO customer investigational medicines not attributed to ICON. Detailed platform ownership, additional AI tools and legacy laboratory assays still require follow-up.'),company('Nissan Chemical Industries Ltd ADR',np,[N,O,H,B,A],'Named semiconductor and life-science materials and medicines captured. Family/grade hierarchy explicit in descriptions. Individual ARC/OptiStack grades, Snowtex semiconductor-specific grades, APIs, animal-health actives and remaining discovery/legacy programmes require further research; no cosmetic or generation-only materials included.')]
(out/'batch-0038.json').write_text(json.dumps({'companies':cs},indent=2));print(sum(len(c['products'])for c in cs))
